#!/usr/bin/env python3
"""Build the Sheets product area from reviewed facts, report samples and editorial copy."""
from pathlib import Path
from html import escape as e
import json,re,hashlib,csv,subprocess
from schema_content import align_graph, dumps
from site_chrome import apply_chrome,render_footer
ROOT=Path(__file__).resolve().parents[1]
BASE='https://lcbridge.app'; P='/google-sheets-integration/'; DATE='2026-10-16'
facts=json.loads((ROOT/'data/product-facts.json').read_text())['google-sheets']; pricing=facts['pricing']
reports=json.loads((ROOT/'data/google-sheets-reports.json').read_text()); report_by={r['id']:r for r in reports}
copy=json.loads((ROOT/'data/google-sheets-report-copy.json').read_text()); articles=json.loads((ROOT/'data/google-sheets-editorial.json').read_text()); docs=json.loads((ROOT/'data/google-sheets-docs.json').read_text())
rendered=json.loads((ROOT/'data/google-sheets-rendered.json').read_text()); register=[]
WAIT=P+'#apply'; SALES='/book-a-call/?product=google-sheets'
icon='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none" aria-hidden="true"><rect width="64" height="64" rx="15" fill="#168A53"/><rect x="14" y="14" width="36" height="36" rx="2" stroke="white" stroke-width="3"/><path d="M26 14V50M38 14V50M14 26H50M14 38H50" stroke="white" stroke-width="3"/></svg>'
def link(path,label,cls='',action=None):return f'<a href="{e(path)}"'+(f' class="{cls}"' if cls else '')+(f' data-analytics-action="{action}"' if action else '')+f'>{label}</a>'
def cta(label='Get early access',cls='btn'):return link(WAIT,label,cls,'early_access_cta_clicked')
def sales(cls='btn secondary'):return link(SALES,'Talk to Sales',cls,'sales_cta_clicked')
def actions():return '<div class="actions">'+cta()+link(P+'templates/','Explore sample dashboards','btn secondary')+'</div>'
def version(asset):return asset+'?v='+hashlib.sha256((ROOT/asset.lstrip('/')).read_bytes()).hexdigest()[:8]
def shell(path,title,description,h1,body,*,kind='WebPage',keyword='',intent='Informational',crumbs=None):
 if 'GoHighLevel' not in title:title=title.replace(' | LC Bridge',' for GoHighLevel | LC Bridge')
 if 'GoHighLevel' not in description:description='For GoHighLevel: '+description
 canonical=BASE+path
 graph=[{'@type':'Organization','@id':BASE+'/#organization','name':'LC Bridge','url':BASE+'/','logo':BASE+'/assets/lcbridge-lockup-black.png'}, {'@type':'WebSite','@id':BASE+'/#website','name':'LC Bridge','url':BASE+'/','publisher':{'@id':BASE+'/#organization'}},{'@type':kind,'@id':canonical+'#webpage','name':title,'url':canonical,'description':description,'isPartOf':{'@id':BASE+'/#website'}}]
 breadcrumbs=[('Home','/'),('Google Sheets integration',P)]
 if path!=P:
  if '/templates/' in path and path!=P+'templates/':breadcrumbs.append(('Report templates',P+'templates/'))
  if '/docs/' in path and path!=P+'docs/':breadcrumbs.append(('Documentation',P+'docs/'))
  if path.startswith('/blog/'):breadcrumbs=[('Home','/'),('Blog','/blog/')]
  breadcrumbs.append((h1,path))
 # Render the same actual hierarchy that is described in JSON-LD.
 if 'class="wrap breadcrumbs"' in body:
  trail='<nav class="wrap breadcrumbs" aria-label="Breadcrumb">'+' / '.join(link(u,e(n)) if i<len(breadcrumbs)-1 else '<span aria-current="page">'+e(n)+'</span>' for i,(n,u) in enumerate(breadcrumbs))+'</nav>'
  body=re.sub(r'<div class="wrap breadcrumbs">.*?</div>',lambda _:trail,body,count=1,flags=re.S)
 graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':BASE+u} for i,(n,u) in enumerate(breadcrumbs)]})
 if kind in ['BlogPosting','TechArticle']:
  graph[-2].update({'headline':h1,'datePublished':DATE,'dateModified':DATE,'author':{'@type':'Person','name':'Karthik Anand'},'publisher':{'@id':BASE+'/#organization'},'image':BASE+'/assets/google-sheets/social.png'})
 graph[2]['about']={'@id':BASE+'/#gohighlevel-platform'}
 # The landing page advertises early access and planned rates, not an active
 # purchase offer. Add SoftwareApplication only when its required commercial
 # evidence can be truthfully published; do not mark it as a free app.
 platform={'@type':'Brand','@id':BASE+'/#gohighlevel-platform',**json.loads((ROOT/'data/product-facts.json').read_text())['platform']};platform.pop('context',None);graph.append(platform)
 faq=[]
 for q,a in re.findall(r'<details><summary>(.*?)</summary>(.*?)</details>',body,re.S):
  if q.endswith('?'):faq.append({'@type':'Question','name':re.sub('<[^>]+>','',q),'acceptedAnswer':{'@type':'Answer','text':re.sub('<[^>]+>','',a)}})
 if faq:graph.append({'@type':'FAQPage','mainEntity':faq})
 schema_source=f'<html><head><title>{e(title)}</title><meta name="description" content="{e(description)}"><meta property="og:image" content="{BASE}/assets/google-sheets/social.png"></head><body><main>{body}</main></body></html>'
 graph=align_graph(graph,schema_source,canonical)
 nav=link(P,'Overview')+link(P+'templates/','Templates')+link(P+'pricing/','Pricing')+link(P+'docs/','Docs')+link('/blog/','Guides')+cta(cls='btn')
 footer=render_footer()
 html=f'''<!doctype html><html lang="en" data-sheets-generated="true"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{canonical}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#106F43"><meta property="og:type" content="{'article' if kind=='BlogPosting' else 'website'}"><meta property="og:url" content="{canonical}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:image" content="{BASE}/assets/google-sheets/social.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{BASE}/assets/google-sheets/social.png"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/inter-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="{version('/assets/fonts.css')}"><link rel="stylesheet" href="{version('/assets/google-sheets/site.css')}"><script type="application/ld+json">{dumps(graph)}</script><script defer src="{version('/assets/analytics-config.js')}"></script><script defer src="{version('/assets/analytics.js')}"></script><script type="module" src="{version('/assets/google-sheets/site.mjs')}"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-row"><a class="product-brand" href="{P}">{icon}<span><strong>Google Sheets integration</strong><small>by LC Bridge</small></span></a><nav class="site-nav" aria-label="Product">{nav}</nav><details class="mobile-menu"><summary>Menu</summary><nav aria-label="Mobile product">{nav}</nav></details></div></header><main id="main">{body}</main>{footer}<dialog id="analytics-dialog" aria-labelledby="analytics-title"><h2 id="analytics-title">Analytics preferences</h2><p id="analytics-description">Optional analytics require your consent before any analytics requests are sent. Hosted forms have their own provider controls.</p><div class="actions"><button type="button" class="btn" data-analytics-consent="granted">Allow analytics</button><button type="button" class="btn secondary" data-analytics-consent="denied">Keep analytics off</button></div></dialog></body></html>'''
 html=apply_chrome(html,path)
 dest=ROOT/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(html+'\n')
 register.append({'url':canonical,'title':title,'description':description,'primaryKeyword':keyword or h1,'secondaryKeywords':'HighLevel; GHL; Google Sheets','intent':intent,'owner':'Karthik Anand','canonical':canonical,'indexable':True,'cta':BASE+WAIT,'status':'Ready for publication','reviewed':DATE,'evidence':'Reviewed product prototype and named primary references; synthetic samples; production acceptance separate'})
 return html

def crumbs(label):return '<div class="wrap breadcrumbs">'+link('/','Home')+' / '+link(P,'Google Sheets integration')+' / '+e(label)+'</div>'
def hero(h1,description,label='Google Sheets × GoHighLevel'):
 return f'<section class="page-hero"><div class="wrap"><p class="eyebrow">{e(label)}</p><h1>{e(h1)}</h1><p class="lede">{e(description)}</p></div></section>'
def section(title,content,*,soft=False,eyebrow='',intro=''):
 return f'<section class="section{" soft" if soft else ""}"><div class="wrap">'+(f'<p class="eyebrow">{e(eyebrow)}</p>' if eyebrow else '')+f'<div class="section-heading"><div><h2>{title}</h2>'+ (f'<p>{intro}</p>' if intro else '')+f'</div></div>{content}</div></section>'
def faq(items):return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def art(r):
 values=[]
 for m in r['result']['metrics'][:3]:
  v=m['value']; unit=m.get('unit','count')
  label='Unavailable' if v is None else (f'${v:,.0f}' if unit=='money' else f'{v:,.1f}'.rstrip('0').rstrip('.')+('%' if unit=='percent' else ''))
  values.append(f'<div><span>{e(m["label"])}</span><b>{label}</b></div>')
 svg=re.search(r'<svg.*?</svg>',rendered[r['id']],re.S)
 visual=svg.group(0) if svg else '<div class="aging-mini">'+''.join(f'<div><span>{e(m["label"])}</span><b>${m["value"]:,.0f}</b></div>' for m in r['result']['metrics'][1:])+'</div>'
 return '<div class="card-art" aria-hidden="true"><div class="thumb-metrics">'+''.join(values)+'</div><div class="thumb-chart">'+visual+'</div></div>'
def cards(ids=None):
 chosen=[report_by[i] for i in ids] if ids else reports
 return '<div class="grid-3">'+''.join(f'<article class="template-card" data-template-card data-category="{e(r["category"])}">{art(r)}<div class="card-body"><span class="card-category">{e(r["category"])}</span><h3>{e(r["name"])}</h3><p>{e(r["description"])}</p>{link(P+"templates/"+r["slug"]+"/","Explore sample →",action="template_cta_clicked")}</div></article>' for r in chosen)+'</div>'
def note():return '<p class="notice">Early access · These public previews use invented records. Join early access to discuss connecting your own GoHighLevel account.</p>'
def sources(items):
 own=[{'title':'LC Bridge data catalog and availability','url':P+'data/'},{'title':'LC Bridge report definitions and samples','url':P+'templates/'}]
 return '<div class="sources"><h2>Sources and further reading</h2><ul>'+''.join('<li>'+link(s['url'],e(s['title']))+'</li>' for s in items+own)+'</ul><p class="small muted">Provider references checked October 16, 2026. Menu labels and source access can change. Product examples describe the reviewed early-access design.</p></div>'
def byline():return '<p class="byline">By Karthik Anand · Updated October 16, 2026</p>'
def endcta():return '<div class="cta-panel"><h2>Make this your reporting workflow.</h2><p>Explore the samples now. Join the existing waitlist to request connected early access, or discuss a predictable subscription for larger workloads.</p><div class="actions">'+cta()+sales()+'</div></div>'

# LANDING
mini='''<div class="hero-shot"><div class="mini-browser"><div class="window-bar"><span class="window-dot"></span><span class="window-dot"></span><span class="window-dot"></span><span class="window-name">CRM Sync / Pipeline &amp; Follow-up</span></div><div class="mini-sheet"><div class="mini-title"><strong>Your pipeline. In perspective.</strong><small>Sample · USD</small></div><div class="mini-kpis"><div><span>Open deals</span><strong>9</strong></div><div><span>Open deal value</span><strong>$22,050</strong></div><div><span>Missing owner</span><strong>1</strong></div></div><div class="mini-chart"><div class="mini-bar"><span>Discovery</span><i><b style="width:46.4%"></b></i><em>$4,800</em></div><div class="mini-bar"><span>Qualified</span><i><b style="width:66.7%"></b></i><em>$6,900</em></div><div class="mini-bar"><span>Proposal</span><i><b style="width:0%"></b></i><em>$0</em></div><div class="mini-bar"><span>Negotiation</span><i><b style="width:100%"></b></i><em>$10,350</em></div></div><div class="mini-table"><div><span>Opportunity</span><span>Owner</span><span>Next step</span></div><div><span>Service quote</span><span>Alex Morgan</span><span>Follow up</span></div><div><span>Additional service</span><span>Jamie Chen</span><span>Review</span></div></div></div></div><p class="sample-caption">Invented sample records · Explore the full dashboard and its definitions.</p></div>'''
body=f'<section class="hero"><div class="wrap hero-grid"><div><span class="kicker">Early access · Google Sheets × GoHighLevel</span><h1>Google Sheets integration for <mark class="hl">GoHighLevel</mark></h1><p class="lede">Bring GoHighLevel data into Google Sheets, build reports from 25 templates, and review spreadsheet changes before updating matching contacts and opportunities.</p>{actions()}<div class="hero-proof"><span>25 open sample reports</span><span>Reviewed CRM updates</span><span>Usage-based pricing</span></div></div>{mini}</div></section>'
body+='<div class="stat-strip"><div class="wrap stat-row"><p><strong>Your data, in a familiar workspace.</strong>Designed for agency teams.</p><p><strong>Import selected records</strong>Fields, filters, and refresh schedules.</p><p><strong>See the business picture</strong>Sales, appointments, payments, and more.</p><p><strong>Review before updating</strong>Explicit confirmation for eligible edits.</p></div></div>'
body+=section('See it end to end, in 90 seconds.','<div class="film"><video controls playsinline preload="none" poster="/assets/google-sheets/levelup/video-poster.jpg" src="/assets/video/gsi-hero-highlevel.mp4" width="1920" height="1080"><track kind="captions" srclang="en" label="English" src="/assets/video/gsi-hero-highlevel.vtt" default></video><p class="sample-caption">Product previews use sample data.</p></div>',eyebrow='The product film')
body+=section('One connection. <mark class="hl">Three useful jobs.</mark>','<div class="grid-3">'+''.join(f'<article class="feature"><span class="number">{n}</span><h3>{h}</h3><p>{p}</p>{link(url,label,"text-link")}</article>' for n,h,p,url,label in [('01','Bring CRM data into Sheets','Choose records, fields, and filters. Preview the data before delivering it to a worksheet, then use a suitable refresh schedule.',P+'docs/importing/','See the import journey →'),('02','Build reports people can inspect','Start with a report template that defines its metrics and supporting records. Keep current snapshots distinct from historical events.',P+'templates/','Browse all 25 samples →'),('03','Update existing records with a review','Edit eligible contact or opportunity fields in the worksheet. Inspect old and new values before explicitly confirming the updates.',P+'docs/reviewed-updates/','Understand reviewed updates →')])+'</div>',eyebrow='From CRM records to useful work')
body+=section('Start with the records you need.','<div class="steps">'+''.join(f'<article class="step"><h3>{h}</h3><p>{p}</p></article>' for h,p in [('Choose data','Select the record type and a relevant scope. Appointments also need a calendar and date window.'),('Select fields','Choose standard and available custom fields, keep record IDs, and set filters.'),('Preview','Inspect rows, field types, missing values, and the destination before running.'),('Import','Deliver to the worksheet and manage refreshes from the saved import.')])+'</div><div class="actions">'+link(P+'docs/getting-started/','Read the getting-started guide','btn secondary')+'</div>',soft=True,eyebrow='The import journey')
body+=section('Beyond a contact list.','<ul class="pill-list">'+''.join(f'<li>{x}</li>' for x in ['Contacts','Opportunities','Businesses','Appointments','Tasks & notes','Invoices','Payments','Orders','Subscriptions','Conversations & messages'])+'</ul><p class="lede">Explore data families and their reporting uses. Live availability depends on source support and account access; advanced history needs its own validated sources.</p><div class="actions">'+link(P+'data/','See fields, directions, and availability','btn secondary')+'</div>',eyebrow='A deliberate data model')
body+=section('Find the report for <mark class="hl">your next decision.</mark>',cards(['pipeline','leads','sales','team','bookings','receivables'])+'<div class="actions">'+link(P+'templates/','Explore all 25 report templates','btn secondary')+'</div>',soft=True,eyebrow='A full library, open to explore',intro='Working sample dashboards with metric definitions, local filters, and the underlying records. No signup needed to inspect them.')
body+=section('Keep control of what moves.','<div class="grid-3"><article class="feature"><h3>Match the existing record</h3><p>Keep CRM IDs and authorized account context with the worksheet. A familiar name is not a reliable record match.</p></article><article class="feature"><h3>Confirm outgoing changes</h3><p>Eligible Contacts and Opportunities updates require Preview changes, Export Preview, and an explicit update action.</p></article><article class="feature"><h3>Recover with context</h3><p>Keep unfinished setup during reconnection, inspect partial results, and review conflicts before sending updates.</p></article></div><p class="small muted" style="margin-top:20px">Scheduled imports and reviewed updates let your team choose when data moves. Connected features are offered through early access.</p>',eyebrow='Designed for accountable operations')
body+=section('Pay <mark class="hl">per record synced.</mark>','<div class="grid-2"><div><p class="lede">250 record transfers included each month. Additional usage starts at <strong>1.5¢ per record transferred</strong>, with automatic volume discounts.</p><p>Each execution counts the primary records it transfers. Transferring the same records again creates usage again.</p><div class="actions">'+link(P+'pricing/','Explore usage pricing','btn')+'</div><p class="small muted">Planned early-access base rates in USD, before applicable markup and tax.</p></div><div class="cta-panel"><h3>Lots of data? Let’s make the pricing work for you.</h3><p>For frequent, high-volume transfers, talk to us about a custom subscription with more predictable costs.</p>'+sales()+'</div></div>',soft=True,eyebrow='Start small. Choose the right fit.')
body+=section('Choose the method that fits your job.','<div class="table-scroll"><table><caption>Ways to move GoHighLevel data into Google Sheets</caption><thead><tr><th>Method</th><th>A useful fit</th><th>What to plan</th></tr></thead><tbody><tr><td>Native CSV</td><td>A one-time export or migration</td><td>File preparation, matching, and repeat manual work</td></tr><tr><td>Native Google Sheets actions</td><td>An event-driven workflow that creates, looks up, updates, or clears rows</td><td>Trigger logic, row identity, and applicable execution pricing</td></tr><tr><td>LC Bridge early-access design</td><td>Configured datasets, report templates, and reviewed existing-record edits</td><td>Source availability, refresh frequency, and record-transfer usage</td></tr></tbody></table></div>'+link('/blog/connect-gohighlevel-google-sheets/','Read the methods and tradeoffs guide →','text-link'),eyebrow='A fair comparison')
body+=section('Questions before you connect.',faq([('Can I connect GoHighLevel to Google Sheets?','Yes: native CSV and Google Sheets workflow actions serve different data-movement needs. LC Bridge is preparing a dedicated early-access connection for configured imports, reports, and reviewed updates.'),('Is this the same product as CRM Sync?','Yes. CRM Sync is the in-app name. The public integration is Google Sheets integration for GoHighLevel by LC Bridge.'),('Does editing a cell automatically update the CRM?','No. Eligible outgoing updates to existing Contacts and Opportunities require a change preview and explicit confirmation. Other object writeback is not promised.'),('Are the dashboards live customer data?','No. All public previews use invented data and a fixed sample period. They do not connect to accounts or change CRM records.'),('How does pricing work?','Planned rates charge per successfully transferred primary record on each execution, with a monthly allowance and graduated volume discounts. A repeat execution transferring the same records adds usage.'),('Can I get a predictable subscription for large volumes?','Yes. Talk to Sales about a custom subscription based on the volume and frequency your team needs.'),('How do I request access?','Use the existing Google Sheets waitlist below. Joining requests early access; it does not install the app, connect an account, or authorize charges.')]),soft=True)
body+=f'''<section class="section" id="apply"><div class="wrap waitlist-grid"><div><p class="eyebrow">Get early access</p><h2>Bring your reporting workflow with you.</h2><p class="lede">Join the Google Sheets integration waitlist. Tell us the job your agency needs to do when we follow up.</p><ul><li>Explore all 25 sample reports today.</li><li>Request access to connected imports and reports.</li><li>Discuss a custom subscription for larger workloads.</li></ul><p class="muted">Want a quick look first? {link(P+'levelup/','See the free templates, then get early access')}.</p><p class="muted">This is an early-access request. No live account connection or billing is activated here.</p><p class="small">The existing hosted form collects your email to manage your early-access request. Read our {link(P+'privacy/','privacy notice')} and {link(P+'terms/','early-access terms')}.</p>{sales()}</div><div class="form-frame"><h3>Google Sheets integration waitlist</h3><iframe id="sheets-waitlist" loading="lazy" title="Google Sheets integration existing waitlist form" src="{facts['waitlistFormUrl']}" data-form-id="na1YK5kycU0nLOzNtWMf"></iframe><p class="form-help">Form not loading? {link(facts['waitlistFormUrl'],'Open the existing waitlist in a new tab')} or {link('mailto:support@lcbridge.app','contact LC Bridge')}. Submission confirmation is provided by the hosted form.</p></div></div></section>'''
shell(P,'GoHighLevel Google Sheets Integration | LC Bridge','Bring GoHighLevel data into Google Sheets. Explore 25 report previews, usage pricing, and reviewed CRM updates. Request LC Bridge early access.','Google Sheets integration for GoHighLevel',body,keyword='GoHighLevel Google Sheets integration',intent='Transactional')

# PRICING
salescard='<aside class="sales-card"><p class="eyebrow">For power users</p><h2>Lots of data? Let’s make the pricing work for you.</h2><p>Syncing large datasets or refreshing frequently? We offer custom subscriptions for high-volume teams that want more predictable costs.</p><p>Tell us what you need, and we’ll work with you on a fair deal. We want you to be happy with both the product and the price—so if pricing is getting in the way, let’s talk.</p><div class="actions">'+sales()+'</div></aside>'
rows=''.join(f'<tr><th scope="row">{label}</th><td>${band["rateMicrousd"]/1e6:g}</td><td>{band["rateMicrousd"]/10000:g}¢</td></tr>' for label,band in zip(['First 1,000 billable transfers','Next 1,000','Next 3,000','Next 25,000','Above 30,000 billable transfers'],pricing['bands']))
body=crumbs('Pricing')+hero('Pay per record synced.','250 record transfers included each month. Additional usage starts at 1.5¢ per record transferred, with automatic volume discounts.','Usage-based pricing · Early access')
body+='<section class="section" style="padding-top:0"><div class="wrap"><div class="pricing-layout"><div class="price-main"><p class="eyebrow">Usage that follows your transfers</p><div class="price-number">1.5¢</div><p class="price-unit">per additional record transferred in the first paid band</p><h2 style="font-size:24px">Start with 250 transfers included.</h2><p>Each execution counts the primary records it successfully transfers. Transferring the same records in another execution creates usage again.</p>'+cta()+'<p class="small muted" style="margin-top:18px">Planned early-access base rates in USD, before applicable markup and tax. No base subscription or per-viewer charge in the usage model.</p></div>'+salescard+'</div><h2>Volume discounts, applied progressively.</h2><p>The allowance is used first. Each subsequent band applies only to transfers within that band, per connected account per calendar month (UTC).</p><div class="table-scroll"><table><caption>Rates after the 250 included monthly record transfers</caption><thead><tr><th>Billable transfer band</th><th>USD per transfer</th><th>Cents per transfer</th></tr></thead><tbody>'+rows+'</tbody></table></div><p class="small muted">The last band begins above 30,250 total transfers after including the monthly allowance. This is a per-transfer charge, not a recurring charge for each distinct stored record.</p>'
body+='''<details class="calculator"><summary>Estimate my monthly cost</summary><p style="margin-top:20px">Explore your records per execution and expected execution frequency. The calculator does not create an account or activate billing.</p><form id="transfer-calculator" novalidate><div class="grid-2"><div class="field"><label for="records-per-run">Primary records transferred per execution</label><input id="records-per-run" type="number" min="0" step="1" inputmode="numeric" required placeholder="Enter a whole number"></div><div class="field"><label for="runs-per-month">Executions in the month</label><input id="runs-per-month" type="number" min="0" step="1" inputmode="numeric" required placeholder="Enter a whole number"></div></div><button class="btn" type="submit">Calculate estimate</button><p id="calculator-error" role="alert"></p><div id="calculator-result" class="calc-result" aria-live="polite" hidden></div></form></details>'''
body+='<script type="application/json" id="pricing-config">'+json.dumps(pricing)+'</script><div class="actions">'+sales()+'</div></div></section>'
body+=section('What counts as a transfer?', '<div class="grid-2">'+''.join(f'<article class="feature"><h3>{h}</h3><p>{p}</p></article>' for h,p in [('A primary record on an execution','A transferred contact, opportunity, invoice, or other supported primary record is a unit. Moving the same record in a new execution creates another unit.'),('Fields and supporting details are bundled','Selected fields, supporting lookup labels, and embedded invoice/order line items do not each become separate transfer units.'),('Retries need the original operation identity','A retry of the same delivery must not create duplicate charges. A genuinely new execution transferring records creates new usage.'),('Reports use the data already delivered','A chart recalculation from existing worksheet data is not another provider transfer. A source refresh that transfers records adds usage.')])+'</div>',soft=True)
body+=section('Pricing questions',faq([('Is the price per record per month?','No. The billable unit is a successfully transferred primary record on each execution. The monthly period applies to the free allowance and volume-discount accumulation.'),('Do repeated refreshes count again?','Yes, when the execution transfers primary records again. A report recalculation from already delivered worksheet data is different from a source refresh.'),('Do I pay for every invoice line?','Embedded invoice lines are bundled with their primary invoice. The same parent rule applies to embedded order lines; standalone primary datasets have their own record identities.'),('Does a failed transfer count?','Planned metering counts successfully delivered primary records. The same delivery operation must not be charged twice when retried or reconciled.'),('Can an agency negotiate a subscription?','Yes. Talk to Sales about a custom subscription based on your expected accounts, transfer volumes, and refresh frequency.'),('Does the estimate include everything on my final bill?','It estimates planned LC Bridge base usage in USD. Applicable account markup and tax can change the final amount. Authorized production rates and billing terms govern actual charges.'),('Where can I read these rates in a simple format?','The product pricing Markdown companion is linked below. It uses the same approved rate definition as this page.')]))
body+=section('Start with the workflow. We’ll help with the fit.',endcta()+ '<p style="margin-top:20px">'+link(P+'pricing.md','Read the pricing Markdown companion')+' · '+link('/blog/gohighlevel-google-sheets-record-transfer-pricing/','Understand record-transfer pricing')+'</p>',soft=True)
shell(P+'pricing/','GoHighLevel Google Sheets Pricing | LC Bridge','Pay per record synced. 250 transfers included monthly, then graduated rates from the first 1.5¢ band. Discuss a predictable high-volume subscription.','Pay per record synced.',body,keyword='GoHighLevel Google Sheets pricing',intent='Transactional')
